mapper.select:
SELECT ct.*, COUNT(cu.user_id) AS currentMembers FROM crew_tb AS ct LEFT JOIN crew_user_tb cu ON ct.crew_id = cu.crew_id
ct.crew_id < #{cursorCrewId}
AND ( crew_name LIKE CONCAT('%', #{search}, '%') OR crew_detail LIKE CONCAT('%', #{search}, '%') OR crew_region LIKE CONCAT('%', #{search}, '%') )
AND crew_region = #{region}
GROUP BY ct.crew_id ORDER BY crew_id DESC LIMIT #{size};
